
export interface WorkspaceShellProps {
  /** Active section key (= pre-T158 view key MapWorkspace switches on). */
  view: string;
  sections: { key: string; label: string; desc: string }[];
  onSection: (key: string) => void;
  children: React.ReactNode;
}

/**
 * Tabbed shell for Map/Plan (T158): the former explore/routes/optimize/
 * trunkfeeder/travel views are tabs over the same MapWorkspace, whose
 * internal `view === '...'` switching is untouched — the active tab key IS
 * the old view key. All workspace props flow through as children so App
 * stays the single prop-wiring owner.
 */
export default function WorkspaceShell({ view, sections, onSection, children }: WorkspaceShellProps) {
  return (
    <div className="flex flex-1 flex-col gap-2 overflow-hidden">
      <div className="flex shrink-0 items-center gap-1.5" role="tablist" aria-label="Workspace sections">
        {sections.map((s) => {
          const active = s.key === view;
          return (
            <button
              key={s.key}
              role="tab"
              aria-selected={active}
              title={s.desc}
              onClick={() => onSection(s.key)}
              className={`rounded-lg border px-3 py-1.5 text-xs font-semibold transition-all ${
                active
                  ? 'border-accent/60 bg-accent/10 text-text-primary'
                  : 'border-border bg-card text-text-secondary hover:bg-card-hover'
              }`}
            >
              {s.label}
            </button>
          );
        })}
      </div>
      {children}
    </div>
  );
}
