import { useEffect, useState } from 'react';
import type { MapEngine } from '../components/MapView';
import type { CorridorGap } from '../types';

/**
 * Owns the map's presentation state: layer visibility toggles, the map
 * engine, the proposed-network focus mode, and the selected corridor seam.
 * The corridor seam is view-scoped policy (Trunk & feeder only), so the
 * clear-on-exit rule lives here too rather than in the composition root.
 */
export function useMapLayers(view: string) {
  const [showRoutes, setShowRoutes] = useState(true);
  const [showSplits, setShowSplits] = useState(false);
  const [showNodes, setShowNodes] = useState(true);
  // Focus mode is the calm default: unselected proposals draw muted grey and
  // only the picked route shows its colours + labels. "Show the complete
  // proposed network" is the opt-in full-colour overview.
  const [showProposedNetwork, setShowProposedNetwork] = useState(false);
  const [showOneWay, setShowOneWay] = useState(false);
  const [mapEngine, setMapEngine] = useState<MapEngine>('auto');
  const [corridorSeam, setCorridorSeam] = useState<CorridorGap | null>(null);

  // Drop the corridor-seam overlay when leaving the Trunk & feeder view.
  useEffect(() => {
    if (view !== 'trunkfeeder') setCorridorSeam(null);
  }, [view]);

  return {
    showRoutes, setShowRoutes,
    showSplits, setShowSplits,
    showNodes, setShowNodes,
    showProposedNetwork, setShowProposedNetwork,
    showOneWay, setShowOneWay,
    mapEngine, setMapEngine,
    corridorSeam, setCorridorSeam,
  };
}
