// P3 split: verbatim move — no JSX edited, only relocated.
// Data shell: owns the four fetches, the settle report, and vintages;
// all rendering lives in HomeView.tsx.
import { useEffect, useRef, useState } from 'react';
import { api } from '../lib/api';
import type { ServiceDay } from '../lib/persist';
import type { BestPilotResponse, MissedTransferConnection } from '../types';
import { useDataVintages } from '../lib/useDataVintages';
import HomeView from './HomeView';

/**
 * Landing spotlight: the zero-cost re-phasing pilot (the first ask), the
 * biggest missed transfer, and the best route to pilot a trunk + feeder
 * redesign, so a first-time user instantly sees where the network is hurting
 * AND what to do about it first. The re-phasing pilot leads: no route
 * changes, no new buses -- staff can run it in weeks. The pilot pick ranks
 * flagged routes by weekday ridership (not just circuity) -- the most winding
 * route is often a low-ridership local loop like the 36, while Route 10
 * carries ~4,000 riders/day on a corridor it can borrow from Route 66.
 */

interface Props {
  period: string;
  /** Service day whose schedule the spotlight cards reflect (switched from
   * the top bar). */
  serviceDay: ServiceDay;
  /** Largest single-route shift the optimizer may apply -- used to rank missed
   * transfers by whether a re-phase can actually rescue them. */
  maxShift?: number;
  refreshToken?: string | number;
  /** Fired once when both spotlight cards have settled (success or error). */
  onLoaded?: () => void;
  onOpenTransfers: () => void;
  onOpenTrunkFeeder: () => void;
  onOpenRoutes: (routeShortName: string) => void;
  onOpenMissed: (routeShortName: string) => void;
  onOpenTravel: () => void;
}

export default function HomePanel({
  period,
  serviceDay,
  refreshToken,
  onLoaded,
  onOpenTransfers,
  onOpenTrunkFeeder,
  onOpenRoutes,
  onOpenMissed,
  onOpenTravel,
  maxShift,
}: Props) {
  const [missed, setMissed] = useState<MissedTransferConnection[] | null>(null);
  const [missedError, setMissedError] = useState<string | null>(null);
  const [missedLoading, setMissedLoading] = useState(true);
  const [missedTick, setMissedTick] = useState(0);

  const [unfixable, setUnfixable] = useState<MissedTransferConnection[] | null>(null);
  const [unfixableError, setUnfixableError] = useState<string | null>(null);
  const [unfixableLoading, setUnfixableLoading] = useState(true);
  const [unfixableTick, setUnfixableTick] = useState(0);

  const [pilot, setPilot] = useState<BestPilotResponse['route']>(null);
  const [pilotError, setPilotError] = useState<string | null>(null);
  const [pilotLoading, setPilotLoading] = useState(true);
  const [pilotTick, setPilotTick] = useState(0);

  // Night crowding alert: routes with p90 >= 80% at late night
  const [nightCrowding, setNightCrowding] = useState<{ route: string; mean: number; p90: number; n: number }[] | null>(null);
  const vintages = useDataVintages();

  useEffect(() => {
    let cancelled = false;
    setMissedError(null);
    setMissed(null);
    setMissedLoading(true);
    (async () => {
      try {
        // limit=10 matches the warm-up cache key so this is a warm hit.
        const m = await api.topMissed({
          period,
          service_day: serviceDay,
          limit: 10,
          max_shift: maxShift,
        });
        if (!cancelled) setMissed(m.connections);
      } catch (e) {
        if (!cancelled) setMissedError(e instanceof Error ? e.message : String(e));
      } finally {
        if (!cancelled) setMissedLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [period, serviceDay, refreshToken, missedTick]);

  // Un-fixable misses: waits no ±max_shift re-phase can bring in-window
  // (long-headway / frequency problems). Shown separately so the home page
  // surfaces the full picture, not just the wins. max_per_departing_route
  // caps how many rows one departing route can hold -- otherwise late night
  // is a wall of "-> 68" rows (every route missing the 74-min Terry Fox at
  // City Centre) and every other problem is starved.
  useEffect(() => {
    let cancelled = false;
    setUnfixableError(null);
    setUnfixable(null);
    setUnfixableLoading(true);
    (async () => {
      try {
        const m = await api.topMissed({
          period,
          service_day: serviceDay,
          limit: 5,
          max_shift: maxShift,
          shiftable: false,
          max_per_departing_route: 2,
        });
        if (!cancelled) setUnfixable(m.connections);
      } catch (e) {
        if (!cancelled) setUnfixableError(e instanceof Error ? e.message : String(e));
      } finally {
        if (!cancelled) setUnfixableLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [period, serviceDay, refreshToken, unfixableTick]);

  useEffect(() => {
    let cancelled = false;
    setPilotError(null);
    setPilot(null);
    setPilotLoading(true);
    (async () => {
      try {
        const p = await api.bestPilot({ period });
        if (!cancelled) setPilot(p.route);
      } catch (e) {
        if (!cancelled) setPilotError(e instanceof Error ? e.message : String(e));
      } finally {
        if (!cancelled) setPilotLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [period, refreshToken, pilotTick]);

  // Night crowding: flag routes where the worst 10% are at/over 80% full at
  // midnight. Only meaningful for the late_night period — showing a "night"
  // alert under AM Rush / Sunday is misleading (T42). The effect and the
  // render both key on ``period``.
  useEffect(() => {
    let cancelled = false;
    if (period !== 'late_night') {
      setNightCrowding(null);
      return () => { cancelled = true; };
    }
    (async () => {
      try {
        const sq = await api.serviceQuality();
        const lateRows = sq.crowding.periods?.['late_night'] ?? [];
        const severe = lateRows
          .filter((r) => (r.p90_percentage ?? 0) >= 80 && (r.n_observations ?? 0) >= 100)
          .map((r) => ({ route: r.route_short_name, mean: r.mean_percentage ?? 0, p90: r.p90_percentage ?? 0, n: r.n_observations ?? 0 }));
        if (!cancelled && severe.length > 0) setNightCrowding(severe);
      } catch {
        // non-critical; home still works without it
      }
    })();
    return () => { cancelled = true; };
  }, [period]);

  // Tell the app shell when the home cards have settled so the startup
  // progress bar can finish its final "home" step. Re-fires on every settle
  // (e.g. after a period change) — the shell treats it as idempotent.
  //
  // The callback lives in a ref so the effect depends only on the load
  // flags, never on onLoaded's identity. A parent that passes an inline
  // arrow (a new function every render) otherwise re-triggers this effect
  // forever: effect -> onLoaded() -> parent setState -> re-render -> new
  // arrow -> effect ... ("Maximum update depth exceeded").
  const onLoadedRef = useRef(onLoaded);
  onLoadedRef.current = onLoaded;
  useEffect(() => {
    if (missedLoading || pilotLoading || unfixableLoading) return;
    onLoadedRef.current?.();
  }, [missedLoading, pilotLoading, unfixableLoading]);

  return (
    <HomeView
      period={period}
      serviceDay={serviceDay}
      maxShift={maxShift}
      refreshToken={refreshToken}
      onLoaded={onLoaded}
      onOpenTransfers={onOpenTransfers}
      onOpenTrunkFeeder={onOpenTrunkFeeder}
      onOpenRoutes={onOpenRoutes}
      onOpenMissed={onOpenMissed}
      onOpenTravel={onOpenTravel}
      missed={missed}
      missedError={missedError}
      missedLoading={missedLoading}
      onRetryMissed={() => setMissedTick((t) => t + 1)}
      unfixable={unfixable}
      unfixableError={unfixableError}
      unfixableLoading={unfixableLoading}
      onRetryUnfixable={() => setUnfixableTick((t) => t + 1)}
      pilot={pilot}
      pilotError={pilotError}
      pilotLoading={pilotLoading}
      onRetryPilot={() => setPilotTick((t) => t + 1)}
      nightCrowding={nightCrowding}
      vintages={vintages}
    />
  );
}
