import { BookOpen, Database, ExternalLink } from 'lucide-react';
import { useEffect, useState } from 'react';
import { DEMO_MODE } from '../lib/static-patch';

/**
 * Demo intro card (T126, 2026-09-17): the "what am I looking at?" layer for
 * first-time readers. The DemoBanner already says the demo is a frozen
 * replay; this card answers the questions a non-technical visitor actually
 * has in their first 30 seconds:
 *   1. What is this?            -> the thesis (promise vs. delivery)
 *   2. How big / how measured?  -> 30-second polls, 24/7, millions of departures
 *   3. Where does the data live?-> the citable Zenodo deposit + findings index
 *
 * Rendered on the home view only, directly below the DemoBanner (see App.tsx).
 * Deliberately three sentences of prose, not a wall: the dashboards below are
 * the evidence — this card is the orientation.
 *
 * The stats line comes from the /api/collector/instrument snapshot (the
 * demo_stats.py derivation — same source the README instrument line uses),
 * NOT a hard-coded string: the hard-coded copy went stale the same week it
 * shipped. Floors are computed the same way the refresh script computes the
 * README's (floor, never round — an up-rounded floor is drift by definition).
 */

type InstrumentStats = {
  available: boolean;
  polls_attempted?: number;
  success_pct?: number | null;
  unique_departures?: number;
};

/** Floor to one decimal — mirrors the refresh script's honest-floor rule. */
function floor1(n: number): number {
  return Math.floor(n * 10) / 10;
}

export default function DemoIntroCard() {
  const [stats, setStats] = useState<InstrumentStats | null>(null);

  useEffect(() => {
    if (!DEMO_MODE) return;
    const base = (import.meta.env.BASE_URL ?? '/').replace(/\/$/, '');
    fetch(`${base}/api-snapshot/instrument-stats.json`)
      .then((r) => (r.ok ? r.json() : null))
      .then((s) => setStats(s))
      .catch(() => setStats(null));
  }, []);

  if (!DEMO_MODE) return null;

  let statsLine: string;
  if (stats?.available && stats.polls_attempted && stats.unique_departures) {
    const pollsK = Math.floor(stats.polls_attempted / 1000);
    const pct =
      stats.success_pct != null ? floor1(stats.success_pct).toFixed(1) : null;
    const depM = floor1(stats.unique_departures / 1_000_000).toFixed(1);
    statsLine = `${pollsK},000+ polls at ${pct ?? '—'}% success, ${depM}M+ unique departures observed`;
  } else {
    // Snapshot absent or unavailable field: say a floor that never goes
    // stale rather than a hard-coded number — the README instrument line
    // stays the canonical floor source.
    statsLine = 'millions of departures observed — exact totals in the findings README';
  }

  return (
    <section
      aria-label="About this demo"
      className="mx-auto mb-3 max-w-5xl rounded-xl border border-border bg-bg/40 p-4 text-sm leading-relaxed text-text-secondary"
    >
      <p className="text-text-primary">
        MiWay publishes a timetable and a real-time feed. This dashboard measures how well
        the actual bus service matches that promise — every scheduled departure, every
        stop, logged around the clock since August 2026: <strong className="text-text-primary">{statsLine}</strong>.
      </p>
      <p className="mt-2">
        Findings — early departures, ghost trips, night crowding, sensor honesty — are published
        weekly with frozen, verifiable snapshots; the full dataset is open and citable.
      </p>
      <div className="mt-3 flex flex-wrap gap-x-5 gap-y-2 text-xs">
        <a
          href="https://doi.org/10.5281/zenodo.22820448"
          target="_blank"
          rel="noreferrer"
          className="inline-flex items-center gap-1.5 font-medium underline hover:text-text-primary"
        >
          <Database className="h-3.5 w-3.5 shrink-0" aria-hidden />
          Open dataset (Zenodo, DOI)
          <ExternalLink className="h-3 w-3 shrink-0" aria-hidden />
        </a>
        <a
          href="https://tapl1338.github.io/miway-findings/"
          target="_blank"
          rel="noreferrer"
          className="inline-flex items-center gap-1.5 font-medium underline hover:text-text-primary"
        >
          <BookOpen className="h-3.5 w-3.5 shrink-0" aria-hidden />
          Findings index
          <ExternalLink className="h-3 w-3 shrink-0" aria-hidden />
        </a>
      </div>
    </section>
  );
}
