// P3 split: verbatim move — no JSX edited, only relocated.
// Pure render component: props in, JSX out. No api imports, no data hooks.
import { AlertTriangle, ArrowRight, CalendarDays, ChevronDown, Clock, Compass, GitBranch, HelpCircle, MapPin, Route as RouteIcon, Settings2, TrendingDown, Users, XCircle } from 'lucide-react';
import type { BestPilotResponse, MissedTransferConnection } from '../types';
import type { ServiceDay } from '../lib/persist';
import TrendsStrip from './TrendsStrip';
import DataVintageBadge from './DataVintageBadge';
import type { Vintages } from '../lib/useDataVintages';
import { SpecRow, SpecSkeleton, ListSkeleton } from './HomeBits';

/**
 * Landing spotlight: the zero-cost re-phasing pilot (the first ask), the
 * biggest missed transfer, and the best route to pilot a trunk + feeder
 * redesign, so a first-time user instantly sees where the network is hurting
 * AND what to do about it first. The re-phasing pilot leads: no route
 * changes, no new buses -- staff can run it in weeks. The pilot pick ranks
 * flagged routes by weekday ridership (not just circuity) -- the most winding
 * route is often a low-ridership local loop like the 36, while Route 10
 * carries ~4,000 riders/day on a corridor it can borrow from Route 66.
 */

const DAY_LABELS: Record<ServiceDay, string> = {
  weekday: 'Weekday',
  saturday: 'Saturday',
  sunday: 'Sunday',
};

const PERIOD_LABELS: Record<string, string> = {
  all_day: 'All Day',
  am_rush: 'AM Rush',
  midday: 'Midday',
  pm_rush: 'PM Rush',
  late_night: 'Late Night (midnight–2am)',
};

const WAIT_TARGET_MIN = 12;

function clockLabel(conn: MissedTransferConnection): string {
  return `${conn.arr_time} → ${conn.dep_time}`;
}

function routeLabel(route: string, direction: string): string {
  return direction ? `Route ${route} ${direction}` : `Route ${route}`;
}

function reasonVerdict(conn: MissedTransferConnection): string {
  if (conn.reason === 'too short') {
    return "Rider can't make it — arrival too close to departure.";
  }
  if (!conn.shiftable_within_max) {
    return "No schedule shift can bring this under the wait cap — it needs more buses or a different routing. See the Blind spots tab.";
  }
  if (conn.walk_alternative_minutes != null) {
    return `The departing bus's whole remaining ride is a ${conn.walk_alternative_minutes} min walk away, so a missed rider can walk instead of waiting out the gap.`;
  }
  return 'Riders wait longer than the target transfer cap.';
}

export interface HomeViewProps {
  period: string;
  /** Service day whose schedule the spotlight cards reflect (switched from
   * the top bar). */
  serviceDay: ServiceDay;
  /** Largest single-route shift the optimizer may apply -- used to rank missed
   * transfers by whether a re-phase can actually rescue them. */
  maxShift?: number;
  refreshToken?: string | number;
  /** Fired once when both spotlight cards have settled (success or error). */
  onLoaded?: () => void;
  onOpenTransfers: () => void;
  onOpenTrunkFeeder: () => void;
  onOpenRoutes: (routeShortName: string) => void;
  onOpenMissed: (routeShortName: string) => void;
  onOpenTravel: () => void;
  missed: MissedTransferConnection[] | null;
  missedError: string | null;
  missedLoading: boolean;
  onRetryMissed: () => void;
  unfixable: MissedTransferConnection[] | null;
  unfixableError: string | null;
  unfixableLoading: boolean;
  onRetryUnfixable: () => void;
  pilot: BestPilotResponse['route'] | null;
  pilotError: string | null;
  pilotLoading: boolean;
  onRetryPilot: () => void;
  nightCrowding: { route: string; mean: number; p90: number; n: number }[] | null;
  vintages: Vintages;
}

export default function HomeView({
  period,
  serviceDay,
  onOpenTransfers,
  onOpenTrunkFeeder,
  onOpenRoutes,
  onOpenMissed,
  onOpenTravel,
  missed,
  missedError,
  missedLoading,
  onRetryMissed,
  unfixable,
  unfixableError,
  unfixableLoading,
  onRetryUnfixable,
  pilot,
  pilotError,
  pilotLoading,
  onRetryPilot,
  nightCrowding,
  vintages,
}: HomeViewProps) {

  // Prefer the best fixable miss so both the pilot card and the detail card
  // show the same connection (avoids showing two different routes).
  const top =
    missed?.find((c) => c.shiftable_within_max && c.fix_net_annual_cost === 0) ??
    missed?.[0] ??
    null;
  const periodLabel = PERIOD_LABELS[period] ?? period;

  // The zero-cost re-phasing ask: the top-ranked miss the schedule alone can
  // fix (no route changes, no new buses). This is the pilot to run first.
  const pilotCandidate =
    missed?.find((c) => c.shiftable_within_max && c.fix_net_annual_cost === 0) ?? null;
  const shiftableCount =
    missed?.filter((c) => c.shiftable_within_max && c.fix_net_annual_cost === 0).length ?? 0;

  // Headline damage numbers: totals over the ranked misses (already loaded),
  // so the page leads with real scale instead of a buried spec row.
  const totalRiderMinYr =
    missed?.reduce((s, c) => s + (c.rider_minutes_per_year ?? 0), 0) ?? 0;
  const totalRiderHrsYr = totalRiderMinYr / 60;

  const waitGaugeMax = top ? Math.max(20, top.wait_minutes + 2) : 20;
  const waitFillPct = top ? Math.min(100, (top.wait_minutes / waitGaugeMax) * 100) : 0;
  const waitTargetPct = (WAIT_TARGET_MIN / waitGaugeMax) * 100;


  return (
    <div className="flex h-full flex-col overflow-y-auto">
      {/* ---- hero snapshot ------------------------------------------------ */}
      <section className="card-glow overflow-hidden rounded-2xl border border-border bg-card">
        <div className="h-1 w-full bg-gradient-to-r from-optimized via-accent to-bottleneck" />
        <div className="p-5">
          <div className="flex items-start gap-3">
            <div className="rounded-xl bg-gradient-to-br from-optimized/25 to-accent/15 p-2.5 shadow-[0_0_14px_rgba(0,230,118,0.15)]">
              <TrendingDown className="h-5 w-5 text-optimized" />
            </div>
            <div className="min-w-0">
              <h2 className="text-lg font-extrabold text-gradient leading-tight">
                Network health at a glance
              </h2>
              <p className="mt-1 text-xs leading-relaxed text-text-muted">
                Where riders hurt most — and what to fix first.
              </p>
            </div>
          </div>
          <div className="mt-4 flex flex-wrap items-center gap-2 border-t border-border pt-3 text-[11px]">
            <span
              className="inline-flex items-center gap-1.5 rounded-full border border-border bg-bg px-3 py-1 text-text-secondary"
              title="Switch the day or time of day with the controls at the top of the page"
            >
              <CalendarDays className="h-3 w-3 text-accent" />
              Showing:{' '}
              <span className="font-semibold text-text-primary">
                {DAY_LABELS[serviceDay]} · {periodLabel}
              </span>
            </span>
            {!missedLoading && !missedError && (
              <span className="inline-flex items-center gap-1.5 rounded-full border border-border bg-bg px-3 py-1 text-text-secondary">
                <Users className="h-3 w-3 text-optimized" />
                <span className="font-semibold text-text-primary">{missed?.length ?? 0}</span>{' '}
                worst connections found
              </span>
            )}
            <DataVintageBadge vintage={vintages.lateness} label="lateness data" />
            <span
              className="inline-flex items-center gap-1.5 rounded-full border border-optimized/30 bg-optimized/10 px-3 py-1 text-[10px] font-semibold text-optimized"
              title="MiWay 2025 Report to the Community: overcrowding incidents fell 53%"
            >
              Overcrowding −53% (2025)
            </span>
          </div>
        </div>
      </section>

      {/* ---- night crowding alert ----------------------------------------- */}
      {/* Only shown for the late_night period — the data is a midnight concern. */}
      {period === 'late_night' && nightCrowding && nightCrowding.length > 0 && (
        <div className="mt-4 overflow-hidden rounded-2xl border border-bottleneck/40 bg-card">
          <div className="h-0.5 edge-gradient-amber" />
          <div className="p-4">
            <div className="flex items-center gap-2">
              <span className="rounded-lg bg-bottleneck/15 p-1.5">
                <AlertTriangle className="h-4 w-4 text-bottleneck" />
              </span>
              <h3 className="text-xs font-bold uppercase tracking-wide text-bottleneck">
                Night crowding alert
              </h3>
            </div>
            <p className="mt-2 text-xs leading-relaxed text-text-secondary">
              {nightCrowding.length} route{nightCrowding.length > 1 ? 's' : ''} run at or over 80% capacity during late night —{' '}
              {nightCrowding.length === 1 ? 'this is' : 'these are'} the last buses of the night.
            </p>
            <div className="mt-2 flex flex-wrap gap-2">
              {nightCrowding.map((r) => (
                <span
                  key={r.route}
                  className="inline-flex items-center gap-1.5 rounded-full border border-bottleneck/30 bg-bottleneck/10 px-2.5 py-1 text-[10px] font-semibold text-bottleneck"
                >
                  Route {r.route}: {r.mean.toFixed(0)}% avg · {r.p90.toFixed(0)}% worst
                </span>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* ---- headline damage numbers --------------------------------------- */}
      {!missedLoading && !missedError && missed && missed.length > 0 ? (
        <div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2">
          <section className="card-glow relative overflow-hidden rounded-2xl border border-danger/40 bg-card p-5">
            <div className="absolute inset-x-0 top-0 h-0.5 edge-gradient-red" />
            <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-wide text-text-secondary">
              <span className="rounded-lg bg-danger/15 p-1.5">
                <Clock className="h-4 w-4 text-danger" />
              </span>
              Longest transfer wait
            </div>
            {top ? (
              <>
                <div className="mt-3 flex items-baseline gap-1.5">
                  <span className="text-5xl font-extrabold tabular-nums leading-none text-danger">
                    {top.wait_minutes}
                  </span>
                  <span className="text-lg font-bold text-text-primary">min</span>
                  {top.wait_minutes > WAIT_TARGET_MIN ? (
                    <span
                      className="ml-auto self-center rounded-full bg-danger/15 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide text-danger"
                      title={`A healthy transfer keeps waits at or under ${WAIT_TARGET_MIN} minutes`}
                    >
                      {Math.round(top.wait_minutes - WAIT_TARGET_MIN)} min over target
                    </span>
                  ) : null}
                </div>
                <div
                  className="relative mt-3 h-6"
                  title={`${top.wait_minutes} min wait against the ${WAIT_TARGET_MIN}-minute healthy-transfer target`}
                >
                  <div className="absolute inset-x-0 top-0 h-1.5 rounded-full bg-border" />
                  <div
                    className="absolute left-0 top-0 h-1.5 rounded-full edge-gradient-red"
                    style={{ width: `${waitFillPct}%` }}
                  />
                  <div
                    className="absolute -top-px h-2 w-0.5 rounded bg-card"
                    style={{ left: `${waitTargetPct}%` }}
                    aria-hidden="true"
                  />
                  <span
                    className="absolute top-2.5 -translate-x-1/2 whitespace-nowrap text-[10px] leading-none text-text-muted"
                    style={{ left: `${waitTargetPct}%` }}
                  >
                    {WAIT_TARGET_MIN}-min target
                  </span>
                </div>
                <p className="mt-1 text-sm leading-relaxed font-medium text-text-primary">
                  Route {top.route_i} → {top.route_j} · {top.stop_name}
                </p>
              </>
            ) : (
              <>
                <div className="mt-3 flex items-baseline gap-1.5">
                  <span className="text-5xl font-extrabold tabular-nums leading-none text-danger">
                    –
                  </span>
                  <span className="text-lg font-bold text-text-primary">min</span>
                </div>
                <p className="mt-2 text-sm leading-relaxed font-medium text-text-primary">No data</p>
              </>
            )}
          </section>

          <section className="card-glow relative overflow-hidden rounded-2xl border border-bottleneck/40 bg-card p-5">
            <div className="absolute inset-x-0 top-0 h-0.5 edge-gradient-amber" />
            <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-wide text-text-secondary">
              <span className="rounded-lg bg-bottleneck/15 p-1.5">
                <TrendingDown className="h-4 w-4 text-bottleneck" />
              </span>
              <span title="Estimated riders per day × extra minutes waited past the 12-minute target × ~261 service days, added up over the ten worst connections below">Time riders lose waiting, per year</span>
            </div>
            <div className="mt-3 flex items-baseline gap-1">
              <span className="text-5xl font-extrabold tabular-nums leading-none text-bottleneck">
                {totalRiderHrsYr.toLocaleString(undefined, { maximumFractionDigits: 0 })}
              </span>
              <span className="text-lg font-bold text-text-primary">hours</span>
            </div>
            <p className="mt-2 text-sm leading-relaxed font-medium text-text-primary">
              extra waiting at these ten stops alone — every wait longer than a healthy 12-minute transfer
            </p>
          </section>
        </div>
      ) : null}

      {/* ---- zero-cost re-phasing pilot (the first ask) --------------------- */}
      {!missedLoading && !missedError && missed && missed.length > 0 ? (
        <div className="mt-4 overflow-hidden rounded-2xl border border-optimized/40 bg-card">
          <div className="h-0.5 edge-gradient-green" />
          <div className="p-4">
            <div className="flex items-center gap-2">
              <span className="rounded-lg bg-optimized/15 p-1.5">
                <Settings2 className="h-4 w-4 text-optimized" />
              </span>
              <h3 className="text-xs font-bold uppercase tracking-wide text-optimized">
                Start here: the zero-cost pilot
              </h3>
            </div>
            {pilotCandidate ? (
              <p className="mt-3 text-xs leading-relaxed text-text-secondary">
                <span className="font-semibold text-text-primary">{pilotCandidate.stop_name}</span>:{' '}
                {routeLabel(pilotCandidate.route_i, pilotCandidate.direction_i)} →{' '}
                {routeLabel(pilotCandidate.route_j, pilotCandidate.direction_j)} —{' '}
                <span className="font-semibold text-danger">{pilotCandidate.wait_minutes} min</span>{' '}
                → fixable with re-timing. No new buses.
              </p>
            ) : (
              <p className="mt-3 text-xs leading-relaxed text-text-secondary">
                No top-{missed.length} miss is fixable by re-timing.
              </p>
            )}
            <div className="mt-3 flex flex-wrap items-center gap-2">
              <span className="inline-flex items-center rounded-full bg-optimized/15 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide text-optimized">
                {shiftableCount}/{missed.length} fixable by re-timing
              </span>
              <button
                onClick={onOpenTransfers}
                className="inline-flex items-center gap-1.5 rounded-lg border border-optimized/50 px-3 py-1.5 text-xs font-semibold text-optimized transition-colors hover:bg-optimized/10"
              >
                Run it in Improve transfers <ArrowRight className="h-3.5 w-3.5" />
              </button>
            </div>
          </div>
        </div>
      ) : null}

      {/* ---- spotlight cards ---------------------------------------------- */}
      <div className="mt-4 grid grid-cols-1 gap-3 lg:grid-cols-2">
        {/* biggest missed transfer */}
        <section className="card-glow overflow-hidden rounded-2xl border border-danger/40 bg-card">
          <div className="h-0.5 edge-gradient-red" />
          <div className="p-4">
            <div className="flex items-center gap-2">
              <span className="rounded-lg bg-danger/15 p-1.5">
                <XCircle className="h-4 w-4 text-danger" />
              </span>
              <h3 className="text-xs font-bold uppercase tracking-wide text-danger">
                Top missed transfer to fix
              </h3>
            </div>

            {missedError ? (
              <div className="mt-3 flex items-center gap-2 rounded-lg border border-danger/40 bg-danger/10 px-3 py-2 text-[11px] text-danger">
                Couldn't load missed transfers: {missedError}
                <button onClick={onRetryMissed} className="ml-auto underline">
                  Retry
                </button>
              </div>
            ) : missedLoading && missed === null ? (
              <SpecSkeleton />
            ) : top ? (
              <>
                <dl className="mt-4 divide-y divide-border overflow-hidden rounded-xl border border-border bg-bg/40">
                  <SpecRow label="Connection">
                    {routeLabel(top.route_i, top.direction_i)} →{' '}
                    {routeLabel(top.route_j, top.direction_j)}
                  </SpecRow>
                  <SpecRow label="Location">
                    <span className="inline-flex items-center gap-1">
                      <MapPin className="h-3 w-3 text-text-muted" />
                      {top.stop_name}
                    </span>
                  </SpecRow>
                  <SpecRow label="Window">
                    {clockLabel(top)} ·{' '}
                    <span className="font-semibold text-danger">{top.wait_minutes} min wait</span>
                  </SpecRow>
                  {top.ride_on_alternative ? (
                    <SpecRow label="Ride on instead">
                      Ride{' '}
                      <span className="font-semibold text-optimized">
                        {top.ride_on_alternative.stops_away}{' '}
                        {top.ride_on_alternative.stops_away === 1 ? 'stop' : 'stops'}
                      </span>{' '}
                      to {top.ride_on_alternative.stop_name} for a{' '}
                      <span className="font-semibold text-optimized">
                        {top.ride_on_alternative.wait_minutes}-min wait
                      </span>{' '}
                      <span className="text-text-muted">
                        (same bus · {top.ride_on_alternative.total_minutes} min total vs{' '}
                        {top.wait_minutes} here)
                      </span>
                    </SpecRow>
                  ) : null}
                  <SpecRow label="What riders face">
                    {top.walk_alternative_minutes != null ? (
                      <>
                        Walk alternative:{' '}
                        <span className="font-semibold text-optimized">
                          {top.walk_alternative_minutes} min
                        </span>
                      </>
                    ) : (
                      <>
                        Wait a full bus interval:{' '}
                        <span
                          className="font-semibold text-text-primary"
                          title="Headway = time between two buses on the same route"
                        >
                          {top.headway_minutes.toFixed(1)} min
                        </span>
                      </>
                    )}
                  </SpecRow>
                  <SpecRow label="Impact score">
                    <span className="font-semibold text-text-primary">{top.weight.toFixed(1)}×</span>{' '}
                    weighted
                    {top.est_riders_per_day != null && top.weight >= 0.5 ? (
                      <>
                        {' · est. '}
                        <span className="font-semibold text-text-primary">
                          ~{Math.round(top.est_riders_per_day)} riders/day
                        </span>
                      </>
                    ) : null}
                         {top.rider_minutes_per_year && top.weight >= 0.5 ? (
                           <>
                             {' · '}
                              <span className="font-semibold text-optimized" title="Estimated riders per day × extra minutes waited past the 12-minute target × ~261 service days">
                                {(top.rider_minutes_per_year / 60).toLocaleString(undefined, { maximumFractionDigits: 0 })} hours/yr lost here
                              </span>
                             {top.fix_net_annual_cost === 0 ? (
                               <span className="text-text-muted" title="Costs nothing to implement — no new buses, drivers, or service hours"> · revenue-neutral fix</span>
                             ) : null}
                           </>
                         ) : null}
                  </SpecRow>
                  {top.real_miss_probability != null ? (
                    <SpecRow label="Real world">
                      {top.real_miss_probability < 0.05 ? (
                        <span className="font-semibold text-optimized">
                          reliable in practice
                        </span>
                      ) : (
                        <span className="font-semibold text-danger">
                          misses ~{top.real_misses_per_week}×/wk
                        </span>
                      )}
                      {top.real_median_wait_minutes != null ? (
                        <span className="text-text-muted">
                          {' · median real wait '}
                          {top.real_median_wait_minutes.toFixed(1)} min
                        </span>
                      ) : null}
                      {top.lateness_n ? (
                        <span className="text-text-muted"> (from {top.lateness_n} obs)</span>
                      ) : null}
                    </SpecRow>
                  ) : null}
                </dl>
                <div className="mt-3 flex flex-wrap items-center gap-2">
                  <span
                    className={`rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide ${
                      top.reason === 'too short'
                        ? 'bg-bottleneck/15 text-bottleneck'
                        : 'bg-danger/15 text-danger'
                    }`}
                  >
                    {top.reason === 'too short' ? 'Just misses the bus' : 'Waits too long'}
                  </span>
                  <span
                    title={top.fix_net_annual_cost === 0 ? 'Shifting this route by a few minutes fixes the connection — no new buses needed' : 'This wait is too long to fix by re-timing — it needs more frequent service or a different route'}
                    className={`rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide ${
                      top.fix_net_annual_cost === 0
                        ? 'bg-optimized/15 text-optimized'
                        : 'bg-bottleneck/15 text-bottleneck'
                    }`}
                  >
                    {top.fix_net_annual_cost === 0
                      ? 'Fixable by re-timing'
                      : 'Needs more service'}
                  </span>
                  <span className="text-[11px] leading-relaxed text-text-muted">
                    {reasonVerdict(top)}
                  </span>
                </div>
                <button
                  onClick={() => onOpenMissed(top.route_i)}
                  className="mt-4 inline-flex items-center gap-1.5 rounded-lg border border-danger/50 px-3 py-1.5 text-xs font-semibold text-danger transition-colors hover:bg-danger/10"
                >
                  See route {top.route_i} on the map <ArrowRight className="h-3.5 w-3.5" />
                </button>
              </>
            ) : (
              <p className="mt-3 text-xs text-text-muted">No missed connections found. Nice.</p>
            )}
          </div>
        </section>

        {/* best route to pilot a redesign */}
        <section className="card-glow overflow-hidden rounded-2xl border border-border bg-card">
          <div className="h-0.5 edge-gradient-blue" />
          <div className="p-4">
            <div className="flex items-center gap-2">
              <span className="rounded-lg bg-accent/15 p-1.5">
                <GitBranch className="h-4 w-4 text-accent" />
              </span>
              <h3 className="text-xs font-bold uppercase tracking-wide text-accent">
                Best route to pilot
              </h3>
              <span className="ml-1 hidden text-[10px] text-text-muted sm:inline">
                — the 6-month redesign phase
              </span>
            </div>

            {pilotError ? (
              <div className="mt-3 flex items-center gap-2 rounded-lg border border-danger/40 bg-danger/10 px-3 py-2 text-[11px] text-danger">
                Couldn't load the pilot route: {pilotError}
                <button onClick={onRetryPilot} className="ml-auto underline">
                  Retry
                </button>
              </div>
            ) : pilotLoading ? (
              <SpecSkeleton rows={6} />
            ) : pilot ? (
              <>
                <dl className="mt-4 divide-y divide-border overflow-hidden rounded-xl border border-border bg-bg/40">
                  <SpecRow label="Route">
                    <span className="font-semibold text-text-primary">
                      Route {pilot.route_short_name}
                    </span>
                    {pilot.weekday_boardings ? (
                      <span className="inline-flex items-center gap-1 font-semibold text-text-primary">
                        <Users className="h-3 w-3 text-optimized" />
                        ~{Math.round(pilot.weekday_boardings).toLocaleString()} riders/day
                      </span>
                    ) : null}
                  </SpecRow>
                  <SpecRow label="Description">
                    {pilot.route_long_name || 'MiWay route'}
                  </SpecRow>
                  {pilot.riders_per_bus != null ? (
                    <SpecRow label="Riders per bus">
                      {pilot.riders_per_bus.toFixed(1)} / bus ·{' '}
                      <span className="text-text-muted">
                        {pilot.weekday_trips != null
                          ? `~${pilot.weekday_trips} runs/day · network median 10.1`
                          : 'network median 10.1'}
                      </span>
                    </SpecRow>
                  ) : null}
                  <SpecRow label="Today">
                    {pilot.length_km.toFixed(1)} km at{' '}
                    <span className="font-semibold text-bottleneck">{pilot.circuity.toFixed(2)}×</span>{' '}
                    circuity
                  </SpecRow>
                  <SpecRow label="Proposed trunk">
                    {pilot.trunk_length_km.toFixed(1)} km at{' '}
                    <span className="font-semibold text-optimized">{pilot.trunk_circuity.toFixed(2)}×</span>
                    {pilot.donor_route ? (
                      <span className="text-text-muted"> · borrows Route {pilot.donor_route}</span>
                    ) : null}
                  </SpecRow>
                  <SpecRow label="Trunk runs">
                    <span className="font-semibold text-text-primary">
                      {pilot.trunk_start_terminal} → {pilot.trunk_end_terminal}
                    </span>
                  </SpecRow>
                </dl>
                <button
                  onClick={onOpenTrunkFeeder}
                  className="mt-4 inline-flex items-center gap-1.5 rounded-lg border border-accent/50 px-3 py-1.5 text-xs font-semibold text-accent transition-colors hover:bg-accent/10"
                >
                  See this split in Trunk &amp; feeder <ArrowRight className="h-3.5 w-3.5" />
                </button>
              </>
            ) : (
              <p className="mt-3 text-xs text-text-muted">
                No routes with a split proposal right now. Nice.
              </p>
            )}
          </div>
        </section>
      </div>

      {/* ---- un-fixable misses -------------------------------------------- */}
      <section className="card-glow mt-4 overflow-hidden rounded-2xl border border-bottleneck/40 bg-card">
        <div className="h-0.5 edge-gradient-amber" />
        <div className="p-4">
          <div className="flex items-center gap-2">
            <span className="rounded-lg bg-bottleneck/15 p-1.5">
              <Clock className="h-4 w-4 text-bottleneck" />
            </span>
            <h3 className="text-xs font-bold uppercase tracking-wide text-bottleneck">
              Waits no schedule shift can fix
            </h3>
          </div>
          <p className="mt-1 text-[11px] leading-relaxed text-text-muted">
            These waits are longer than the optimizer's shift budget can reach — fixing them needs
            a frequency or routing change, not a re-timing.
          </p>

          {unfixableError ? (
            <div className="mt-3 flex items-center gap-2 rounded-lg border border-bottleneck/40 bg-bottleneck/10 px-3 py-2 text-[11px] text-bottleneck">
              Couldn't load un-fixable waits: {unfixableError}
              <button onClick={onRetryUnfixable} className="ml-auto underline">
                Retry
              </button>
            </div>
          ) : unfixableLoading && unfixable === null ? (
            <ListSkeleton />
          ) : unfixable && unfixable.length > 0 ? (
            <div className="mt-3 flex flex-col divide-y divide-border overflow-hidden rounded-xl border border-border bg-bg/40">
              {unfixable.slice(0, 3).map((conn) => (
                <div key={`${conn.stop_id}-${conn.route_i}-${conn.route_j}-${conn.arr_time}`} className="flex items-center gap-3 px-3 py-2.5">
                  <span className="w-14 shrink-0 text-right text-xs font-bold tabular-nums text-bottleneck">
                    {conn.wait_minutes} min
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="truncate text-xs font-semibold text-text-primary">
                      {routeLabel(conn.route_i, conn.direction_i)} →{' '}
                      {routeLabel(conn.route_j, conn.direction_j)}
                    </div>
                    <div className="truncate text-[10px] text-text-muted">
                      {conn.stop_name} · {clockLabel(conn)}
                    </div>
                  </div>
                  <span className="shrink-0 text-right text-[10px] font-semibold text-text-secondary">
                    {conn.headway_minutes.toFixed(1)} min between buses
                  </span>
                </div>
              ))}
            </div>
          ) : (
            <p className="mt-3 text-xs text-text-muted">
              No un-fixable waits found. Nice.
            </p>
          )}
        </div>
      </section>

      {/* ---- measured week-over-week trends (T152c) ----------------------- */}
      <TrendsStrip />

      {/* ---- next steps --------------------------------------------------- */}
      <section className="mt-4 rounded-2xl border border-border bg-card p-4">
        <div className="flex items-center gap-2">
          <span className="rounded-lg bg-accent/15 p-1.5">
            <Compass className="h-4 w-4 text-accent" />
          </span>
          <h3 className="text-xs font-bold uppercase tracking-wide text-text-secondary">
            What would you like to do?
          </h3>
        </div>
        <div className="mt-3 flex flex-col gap-2">
          <button
            onClick={onOpenTransfers}
            className="group flex items-center gap-3 rounded-xl border border-border bg-bg/40 px-3 py-3 text-left transition-colors hover:border-optimized/50 hover:bg-optimized/10"
          >
            <span className="rounded-lg bg-optimized/15 p-2">
              <Settings2 className="h-4 w-4 text-optimized" />
            </span>
            <span className="min-w-0 flex-1">
              <span className="block text-xs font-bold text-text-primary">Improve transfers</span>
              <span className="block text-[10px] text-text-muted">
                Shift schedules so riders wait less between buses
              </span>
            </span>
            <ArrowRight className="h-4 w-4 shrink-0 text-text-muted transition-transform group-hover:translate-x-0.5 group-hover:text-optimized" />
          </button>
          <button
            onClick={onOpenTrunkFeeder}
            className="group flex items-center gap-3 rounded-xl border border-border bg-bg/40 px-3 py-3 text-left transition-colors hover:border-accent/50 hover:bg-accent/10"
          >
            <span className="rounded-lg bg-accent/15 p-2">
              <GitBranch className="h-4 w-4 text-accent" />
            </span>
            <span className="min-w-0 flex-1">
              <span className="block text-xs font-bold text-text-primary">
                Explore trunk &amp; feeder splits
              </span>
              <span className="block text-[10px] text-text-muted">
                Turn a winding route into a direct trunk + feeder branch
              </span>
            </span>
            <ArrowRight className="h-4 w-4 shrink-0 text-text-muted transition-transform group-hover:translate-x-0.5 group-hover:text-accent" />
          </button>
           <button
             onClick={() => onOpenRoutes('')}
             className="group flex items-center gap-3 rounded-xl border border-border bg-bg/40 px-3 py-3 text-left transition-colors hover:border-bottleneck/50 hover:bg-bottleneck/10"
           >
             <span className="rounded-lg bg-bottleneck/15 p-2">
               <RouteIcon className="h-4 w-4 text-bottleneck" />
             </span>
             <span className="min-w-0 flex-1">
               <span className="block text-xs font-bold text-text-primary">
                 Review route quality
               </span>
               <span className="block text-[10px] text-text-muted">
                 See flagged winding routes and their scores
               </span>
             </span>
             <ArrowRight className="h-4 w-4 shrink-0 text-text-muted transition-transform group-hover:translate-x-0.5 group-hover:text-bottleneck" />
           </button>
           <button
             onClick={onOpenTravel}
             className="group flex items-center gap-3 rounded-xl border border-border bg-bg/40 px-3 py-3 text-left transition-colors hover:border-accent/50 hover:bg-accent/10"
           >
             <span className="rounded-lg bg-accent/15 p-2">
               <MapPin className="h-4 w-4 text-accent" />
             </span>
             <span className="min-w-0 flex-1">
               <span className="block text-xs font-bold text-text-primary">
                 Plan a journey
               </span>
               <span className="block text-[10px] text-text-muted">
                 Compare today's trip vs. the optimized schedule
               </span>
             </span>
             <ArrowRight className="h-4 w-4 shrink-0 text-text-muted transition-transform group-hover:translate-x-0.5 group-hover:text-accent" />
           </button>
         </div>
      </section>

      {/* ---- quick glossary ----------------------------------------------- */}
      <details className="group mt-4 rounded-2xl border border-border bg-card p-4">
        <summary className="flex cursor-pointer list-none items-center gap-2 text-xs font-semibold text-text-secondary hover:text-text-primary [&::-webkit-details-marker]:hidden">
          <span className="rounded-lg bg-text-muted/15 p-1.5">
            <HelpCircle className="h-3.5 w-3.5" />
          </span>
          Quick glossary — terms used on this page
          <ChevronDown className="ml-auto h-3.5 w-3.5 shrink-0 text-text-muted transition-transform group-open:rotate-180" />
        </summary>
        <div className="mt-3 grid grid-cols-1 gap-1.5 sm:grid-cols-2">
          {[
            { term: 'Headway', plain: 'Time between two buses on the same route. A bus every 15 min = 15 min headway.' },
            { term: 'Re-phasing', plain: 'Shifting a route\'s departure times by a few minutes so buses arrive in sync at transfer points.' },
            { term: 'Circuity', plain: 'How much longer a route is than a straight line between its ends. 2.0× = twice as long as needed.' },
            { term: 'Trunk & feeder', plain: 'A redesign where a winding route is split into a direct main line (trunk) plus shorter branch routes (feeders).' },
            { term: 'Revenue-neutral', plain: 'Costs nothing to implement — no new buses, drivers, or service hours.' },
            { term: 'Rider-minutes', plain: 'Total waiting time for all riders combined. 100 riders waiting 10 min = 1,000 rider-minutes.' },
          ].map((g) => (
            <div key={g.term} className="rounded-lg border border-border bg-bg/60 px-2.5 py-2">
              <span className="text-[11px] font-bold text-text-primary">{g.term}</span>
              <span className="text-[10px] leading-snug text-text-muted"> — {g.plain}</span>
            </div>
          ))}
        </div>
      </details>

      <p className="mt-6 px-2 pb-2 text-center text-[11px] leading-relaxed text-text-muted">
        Figures are order-of-magnitude estimates built on MiWay's published timetable and observed
        live-bus data — not measured counts. Riders/day figures are estimated where onboard counts
        are unavailable.
      </p>
    </div>
  );
}
