import { useCallback, useEffect, useRef, useState } from 'react';

/**
 * P2 — one owner for panel data plumbing (overhaul Option B).
 *
 * Every panel repeated the same ~20 lines: `data/error/loading` state +
 * a mount effect + (sometimes) an abort/interval rig — with per-panel
 * drift in exactly the places that caused past bugs (the T159 #2 stranded
 * poll class, stale-poll state writes). This hook is the single owner:
 *
 *   fetch   → on mount, and whenever `deps` change (default `[]`)
 *   loading → true until first settle; stays false on background refreshes
 *   error   → message string; cleared before each load; panels render it
 *             with their own wording (hook never renders)
 *   empty   → `isEmpty(data)` callback lets panels distinguish "endpoint
 *             returned a body with no rows" from "still loading"
 *   poll    → `pollMs` re-runs the fetcher on an interval (first tick one
 *             interval after mount — the CoveragePanel contract polling.test
 *             pins; a tick landing mid-load aborts the stale load, newest
 *             wins)
 *   abort   → a new load aborts the previous in-flight one (P0.8: a
 *             5-minute-old poll response is worse than an aborted request);
 *             unmount aborts in-flight loads and stops the timer
 *
 * The fetcher receives the load's AbortSignal and passes it to api.* calls
 * that accept `{ signal }`. Panels keep their own render logic — this hook
 * deliberately owns STATE, not markup.
 *
 * Safety net: `tests/usePanelData.test.tsx` pins the contract with fake
 * timers (mount-once, poll boundary, overlap-abort, unmount discipline).
 */

export interface UsePanelDataOptions<T> {
  /** Called on mount + dep change + poll tick + retry. Receives the load's
   *  AbortSignal; forward it to api calls that accept `{ signal }` so a
   *  newer load can abort a stale one. */
  fetcher: (signal: AbortSignal) => Promise<T>;
  /** Effect deps: reload whenever these change (like a useEffect dep array). */
  deps?: readonly unknown[];
  /** Poll interval in ms; omit for fetch-once panels. */
  pollMs?: number;
  /** Mark the payload as "no content" so panels can render an empty state
   *  instead of data view. Default: never empty. */
  isEmpty?: (data: T) => boolean;
  /** Skip fetching entirely (e.g. a sub-card that's not mounted yet). */
  enabled?: boolean;
}

export interface UsePanelDataResult<T> {
  /** Latest payload; null until the first successful load. */
  data: T | null;
  /** Error message from the most recent load; null when the load succeeded.
   *  A successful load CLEARS a previous error (stale error must not outlive
   *  fresh data). */
  error: string | null;
  /** True until the first load settles; also true again while a dep-triggered
   *  reload runs with no data yet. NOT set by background poll refreshes. */
  loading: boolean;
  /** True when `data` is set AND isEmpty(data) — a settled, empty payload. */
  empty: boolean;
  /** Manually re-run the fetcher (Retry buttons, Refresh icons). */
  reload: () => void;
  /** True while any load (including background polls) is in flight — for
   *  RefreshCw spin states. */
  refreshing: boolean;
}

function messageOf(e: unknown): string {
  return e instanceof Error ? e.message : String(e);
}

export function usePanelData<T>({
  fetcher,
  deps = [],
  pollMs,
  isEmpty,
  enabled = true,
}: UsePanelDataOptions<T>): UsePanelDataResult<T> {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(enabled);
  const [refreshing, setRefreshing] = useState(false);

  // The load sequence number: only the newest load may write state. A ref,
  // not the AbortController alone, because an aborted fetch REJECTS (its
  // catch must not write an error) while a fetch that ignores the signal
  // RESOLVES late (its then must not write data either). Covers both.
  const seqRef = useRef(0);
  const controllerRef = useRef<AbortController | null>(null);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Stable identity for the latest inputs without making the load callback
  // a dependency of the effect that runs it.
  const fetcherRef = useRef(fetcher);
  fetcherRef.current = fetcher;
  const isEmptyRef = useRef(isEmpty);
  isEmptyRef.current = isEmpty;

  const stopTimer = useCallback(() => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const load = useCallback(() => {
    // Abort the previous in-flight load (P0.8 discipline) and bump the seq:
    // an older load can no longer touch state even if its api call ignores
    // the abort signal.
    controllerRef.current?.abort();
    seqRef.current += 1;
    const seq = seqRef.current;
    const controller = new AbortController();
    controllerRef.current = controller;

    setRefreshing(true);
    (async () => {
      try {
        const d = await fetcherRef.current(controller.signal);
        if (seq !== seqRef.current) return; // superseded: don't touch state
        setData(d);
        setError(null);
      } catch (e) {
        if (seq !== seqRef.current) return; // superseded or aborted
        setError(messageOf(e));
      } finally {
        if (seq === seqRef.current) {
          setLoading(false);
          setRefreshing(false);
        }
      }
    })();
  }, []);

  // Dep-keyed load lifecycle: runs on mount, whenever deps change, or when
  // `enabled`/reload flips. The poll interval fires every pollMs (first tick
  // at pollMs after mount — CoveragePanel's pinned contract); a tick that
  // lands while a load is in flight ABORTS it (newest poll wins — the P0.8
  // overlap contract). Timer stops on unmount/dep change.
  const [reloadKey, setReloadKey] = useState(0);
  const reload = useCallback(() => setReloadKey((k) => k + 1), []);
  const depsKey = deps.join('\u0000');

  useEffect(() => {
    if (!enabled) {
      stopTimer();
      return;
    }
    seqRef.current += 1; // invalidate any in-flight load from a previous key
    setLoading((prev) => prev || data === null);
    setError(null);
    void load();

    if (pollMs == null) return;

    const timer = setInterval(() => void load(), pollMs);
    timerRef.current = timer;
    return () => {
      clearInterval(timer);
      timerRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [depsKey, enabled, reloadKey, pollMs, load, stopTimer]);

  // Unmount: in-flight load is stale by definition.
  useEffect(() => {
    return () => {
      seqRef.current += 1;
      controllerRef.current?.abort();
      stopTimer();
    };
  }, [stopTimer]);

  const empty =
    data != null && isEmptyRef.current != null ? isEmptyRef.current(data) : false;

  return { data, error, loading, empty, reload, refreshing };
}
