import { useCallback, useMemo, useState } from 'react';
import type { TravelLine, TravelMarker } from '../components/MapView';
import { BASELINE_COLOR, OPTIMIZED_COLOR } from '../lib/viewConfig';
import type {
  TravelCompareResponse,
  TravelItinerary,
  TravelPoint,
} from '../types';

/** Itinerary legs -> map polylines, colored/dashed by today-vs-improved. */
function itinToLines(
  prefix: string,
  color: string,
  dash: string | undefined,
  itin: TravelItinerary,
): TravelLine[] {
  return itin.legs.map((leg, i) => ({
    id: `${prefix}-${i}`,
    label: leg.kind === 'bus' ? `Route ${leg.route} (${prefix})` : `Walk leg ${i + 1} (${prefix})`,
    color,
    dashArray: dash,
    weight: 4,
    points: leg.path,
  }));
}

/**
 * Owns the travel planner's state: the origin/destination picks (from the
 * panel's autocomplete or map clicks) and the returned itineraries, plus the
 * derived map overlay (lines + markers) rendered by MapView.
 */
export function useTravelPlanner(view: string) {
  const [travelItin, setTravelItin] = useState<Pick<
    TravelCompareResponse,
    'baseline' | 'optimized' | 'origin' | 'destination'
  > | null>(null);
  const [travelPicks, setTravelPicks] = useState<{
    origin: TravelPoint | null;
    destination: TravelPoint | null;
    nextPick: 'origin' | 'destination';
  }>({ origin: null, destination: null, nextPick: 'origin' });

  const travelLines = useMemo<TravelLine[]>(() => {
    if (!travelItin) return [];
    const lines: TravelLine[] = [];
    if (travelItin.baseline) lines.push(...itinToLines('today', BASELINE_COLOR, '7 5', travelItin.baseline));
    if (travelItin.optimized) lines.push(...itinToLines('optimized', OPTIMIZED_COLOR, undefined, travelItin.optimized));
    return lines;
  }, [travelItin]);

  const travelMarkers = useMemo<TravelMarker[]>(() => {
    const markers: TravelMarker[] = [];
    const o = travelPicks.origin;
    const d = travelPicks.destination;
    if (o?.lat != null && o?.lon != null)
      markers.push({ id: 'origin', label: o.name ?? 'Origin', color: '#22c55e', lat: o.lat, lon: o.lon });
    if (d?.lat != null && d?.lon != null)
      markers.push({ id: 'dest', label: d.name ?? 'Destination', color: '#2563eb', lat: d.lat, lon: d.lon });
    return markers;
  }, [travelPicks]);

  /** Map clicks only pick points while the travel view is active. */
  const onMapPick = useCallback(
    (lat: number, lon: number) => {
      if (view !== 'travel') return;
      setTravelPicks((prev) => {
        const target = prev.nextPick;
        const pt: TravelPoint = { mode: 'point', lat, lon, name: null };
        return {
          origin: target === 'origin' ? pt : prev.origin,
          destination: target === 'destination' ? pt : prev.destination,
          nextPick: target === 'origin' ? 'destination' : 'origin',
        };
      });
    },
    [view],
  );

  return {
    travelPicks, setTravelPicks,
    travelItin, setTravelItin,
    travelLines,
    travelMarkers,
    onMapPick,
  };
}
